// GUIDE data (wave 4, module 'guide'): the registry of discoverable features, the Algorithm's tip lines, the first-time tutorial
// steps and every UI string. PURE DATA (no imports): every text is an [en, tr, ru] triple, picked with pick(arr, lang).
// Tips are written in the voice of The Algorithm (creepy-corporate, dry): short, never longer than ~120 characters, and always say
// HOW (a key or a terminal command). Contexts (`when`) are flag names computed by guide.js from the live game (see CTX_FLAGS).
//
// Feature fields: id, cat, name[3], how[3] (multi-line how-to for GUIDE <id>), tips[[3]...] (Algorithm one-liners),
//   cmds  terminal words that mark the feature used         keys  KeyboardEvent.code values that mark it used
//   panel panel id from classifyPanel()                     evt   mods-bus event / internal event id that marks it used
//   when  [ctx flags] ALL must be true for the tip          prio  base score (1..10)
//   needs module name on `game` (or 'cmd:<word>' = a registered terminal command) that must exist; an array = any of them             minLevel  hide the tip below this profile level
export const LANGS3 = ['en', 'tr', 'ru'];
export const pick = (arr, lang = 'en') => {
  if (!arr) return '';
  if (typeof arr === 'string') return arr;
  const i = lang === 'tr' ? 1 : lang === 'ru' ? 2 : 0;
  return arr[i] !== undefined && arr[i] !== null && arr[i] !== '' ? arr[i] : arr[0];
};
export const fmt = (s, v = {}) => String(s).replace(/\{(\w+)\}/g, (m, k) => (v[k] !== undefined && v[k] !== null ? String(v[k]) : m));

