  gear: ['GEAR & PROGRESSION', 'EKİPMAN & GELİŞİM', 'СНАРЯЖЕНИЕ И ПРОГРЕСС'],
  magic: ['MAGIC & COMBAT', 'BÜYÜ & SAVAŞ', 'МАГИЯ И БОЙ'],
  crew: ['CREW & SOCIAL', 'EKİP & SOSYAL', 'КОМАНДА'],
  world: ['WORLD & ENDGAME', 'DÜNYA & OYUN SONU', 'МИР И ЭНДГЕЙМ'],
  meta: ['LORE & META', 'HİKAYE & META', 'ЛОР И МЕТА'],
